-- Additional Circle chat messages: April 26 – May 19, 2026
-- Run this AFTER 20260521_circle_chat.sql (which covers April 21–25)

INSERT INTO community_messages (chat_id, email, name, content, media, created_at) VALUES
  ('group', 'confi1@hotmail.com', 'Kelly Williams', 'When the brain just isn''t braining 🧠 Today I have hours I could put into practicing, but I''m stumbling in pieces I know and have zero focus to learn anything new. How long do you guys give before accepting defeat?!?', '[]', '2026-04-26 07:35:00+01'),
  ('group', 'matthew@matthewcawood.com', 'Matthew Cawood', 'Hello team, a quick update 🙂

I''m going to make a couple of changes to make things more useful here:

Firstly, the live sessions will now be Live Practice Clinics, each one focused on a specific topic (e.g. fixing mistakes, what to practise when stuck, how to play chord patterns etc.)

I''m also going to start posting a Weekly Practice Focus. This will be a simple idea you can actively apply to your own playing that week.

My goal is to make everything here a bit more practical and directly useful for your playing!', '[]', '2026-04-28 09:45:00+01'),
  ('group', 'confi1@hotmail.com', 'Kelly Williams', 'I just used the passage fixer for the first time...seems to work!! After practicing the bar I was stuck on, I played the piece all the way through first time with no mistakes 😀', '[]', '2026-04-28 11:32:00+01'),
  ('group', 'bobbymi003@gmail.com', 'BOBBY', 'Hi my name is Bobby , I''m 23 , I''m from the UK, and I started playing piano about 3 months ago.

I''ve been trying to stay consistent with it, usually practicing around 30 minutes a day. Some days are better than others, but I''m sticking with it. When I picked up a piano from my first paycheck 3 years ago I thought I would be playing Tchaikovsky by the end of the month, however the instrument broke my spirit and it became a glorified clothes stand in my room untill January of 2026. I have decided however long it takes , however hard it is , I will learn to play the piano and I don''t care if it takes me till my last breath (however I want to improve as fast as possible hehe )

Right now I''m mainly working on getting the basics right—playing pieces slowly, improving my coordination, and I''ve just started practicing scales like C major and G major in practice from last week after I saw a video on why they are important they are. I have finished the Michael Aaron''s grade 1 book and I hated every single piece inside it.

I''d say I''m still a beginner, especially when it comes to playing hands together, but I can feel myself improving.

My goal is just to keep going and get to a point where I can play more advanced pieces properly by the end of the year, play songs for my loved ones and maybe inspire someone to learn someday. I picture myself old and grey someday playing Chopin sonatas impressing the ladies at the old age home with me . But please don''t be shy of helping me , I have nothing to lose and everything to gain in this community. 🎹❤️👍🏼', '[]', '2026-04-30 16:21:00+01'),
  ('group', 'denzelriwai1@gmail.com', 'Denzel R Riwai', 'I''m Denzel Riwai, 21, from New Zealand, but I live in Queensland, Australia. I''ve been teaching myself piano for two months now, using access to the internet, of course. I started with an Alesis Harmony 66, super beginner piano, I learned the map of the keyboard, sharps, flats, etc. but playing songs on it proved more than unsatisfying. I upgraded to a Yamaha 145BT, at the time it arrived I had learned and memorised a few right hand parts of a few songs. Still struggling with hand independence at the time.

I learned how to play songs through synesthesia, the timing through common sense. I learned the bass and treble clef up to 5 ledger lines above and below, bought Matt''s sight-reading book to practice it daily. I couldn''t find anything worth learning on the piano.

I joined this community because I''m not going to let my progress disappear, I''ve got great momentum. So I started learning Rachmaninoff''s Prelude in G minor, and Prelude in C sharp minor, I''m halfway through them both.

At my level, I''m obviously a beginner, but I''ve achieved enough to learn.

I learned a song called The Call of Silence, it''s a three chord loop in the left hand, some right hand melodies, chords and then octaves. After about 5 minutes I started adding my own notes in the right hand and arpeggiating the left hand chords. Playing with it to make it more better and use actual effort. Sorry it''s hard to describe your level isn''t it? I can play the piano, any song people around me ask for I can play it by the end of the hour. My main struggle is finding something worth the effort of learning to PLAY.

I''m going to master the instrument, playing by ear and sight reading. I''ll practice pieces until I don''t have a mechanical obstacle to learning songs.

I apologise for the lengthy introduction, I''m content if you skip over it, I have read all of yours, and it''s amazing to see so many people from different areas of the world in one place. I look forward to seeing how everyone else is fairing with the piano', '[]', '2026-05-01 04:31:00+01'),
  ('group', 'denzelriwai1@gmail.com', 'Denzel R Riwai', 'Hey everyone 👋, I''m just curious about what pieces everyone is working on, I''d like to do some sight reading today so I''ll take a look into whatever your working on. I''m also wondering how you all like to practice.. at the beginner level almost any work on the piano is worth it, I''m just curious about the things you all consistently do.. any thing you have saved as practice you enjoy it believe helped you.. for example, I like to warm up my hands by improvising or transcribing.. a small quirk I find beneficial for checking a few boxes at once with small amounts of time.

( Yes, I will absolutely steal your techniques .. even if you don''t believe it, your experience and your hours have already made you uniquely knowledgeable... )

Also... I have no idea how the experts operate.. for example, Matt are you at a level where you can just... Not practice? Do you still learn pieces regularly?

No matter who you are, I appreciate your time.', '[]', '2026-05-02 21:14:00+01'),
  ('group', 'danielduordoe@yahoo.co.uk', 'Daniel Duordoe', 'Was Bach really a baroque/classical musician? I have been playing Air on the G string for a month and I am convinced he sounds pretty jazzy/bluesy 😂', '[]', '2026-05-05 08:25:00+01'),
  ('group', 'jonathan.arroyo@12yfilms.com', 'jonathan arrow', 'Hi, I''m Jonathan from NYC. I''m a new member. I truly love Matthew''s point of views on his Youtube channel. I am the owner/operator of 12Y films in NYC/NJ. I work with a few Fortune 500 companies and public clients (Google, LinkedIn, UFC), but most of my work is internal corporate communications and commercials for the Healthcare Sector. I started playing the piano this January, but I''m currently "stuck." I''ve spent a lot of time learning music theory and playing the actual piano, so I no longer feel like "how-to" videos are adequate because they seem too easy, but I''m also not far enough in my journey to be an "intermediate" player. I''m hoping to learn from everyone here and figure out what my next move will be. I have lots of weaknesses in my piano skills, but this seems to be the right place to start fixing them. I''m 42 but want to grow up to be Hans Zimmer. lol. Honestly, I don''t want to be a performer or pianist, I just want to feel comfortable enough to create my own background/ambient music that I can apply to the commercials and communication videos I make. I see it as an add-on service where I can charge my clients for licensing my own music. I''m most comfortable in Cubase 15 Pro on my mac, but also have fun creating EDM in Ableton. My favorite instrument is my Exquis MPE MIDI player. Good luck to everyone here!
Attachment image', '[]', '2026-05-05 15:16:00+01'),
  ('group', 'danielduordoe@yahoo.co.uk', 'Daniel Duordoe', 'I just attempted to sightread the first movement of Beethoven''s Moonlight Sonata... Let''s just say it''s a lot harder than it sounds. Good night.', '[]', '2026-05-05 20:40:00+01'),
  ('group', 'danielduordoe@yahoo.co.uk', 'Daniel Duordoe', 'https://youtu.be/uA7Vo4zVYMI?si=26zyu-vkeKUNt01h. Apparently people don''t stop and applaud when you play a nocturne at the train station.
YouTube: What Really Happens When You Play Piano at a Station', '[]', '2026-05-06 04:20:00+01'),
  ('group', 'bobbymi003@gmail.com', 'BOBBY', 'Good afternoon fellow pianists, I have a question to ask you. Is it just me that feels like throwing my piano out the window and chopping off my fingers off after a bad practice session. Like honestly I think about stopping this torturous hobby every week for good, but something about this instrument just pulls me back every time. I don''t know why my fingers won''t work 😢😭. Please share any stories or tips so i don''t give up.', '[]', '2026-05-06 15:44:00+01'),
  ('group', 'michaelpage05@hotmail.co.uk', 'Michael Page', 'A birthday present from my wife 😁
Attachment image', '[]', '2026-05-07 04:19:00+01'),
  ('group', 'michaelpage05@hotmail.co.uk', 'Michael Page', 'I have a question. Is anyone working through a work book like piano adventures? If they are how are they recording it in the Practice Log. Just looking for ideas how to log it.', '[]', '2026-05-07 07:57:00+01'),
  ('group', 'matthew@matthewcawood.com', 'Matthew Cawood', '@Michael Page We can''t be a group for pianists and not play happy birthday! I opted to play with Disney-esk-ness as you got a Disney book 😀
[Video attached]', '[]', '2026-05-07 08:46:00+01'),
  ('group', 'tdalavoy@gmail.com', 'Tulika Dalavoy', 'This is an issue I frequently have while recording videos for exams. The dynamics is not very clear in the video recording. While playing the pieces, I can clearly hear the difference between loud and soft. But when I listen to the recording, the "soft" does not sound very soft. Sometimes I intentionally play the next line really loud to bring out the difference. I record through a cable to avoid background noise. Does anyone have suggestions to get around this so that I can express the dynamics better?', '[]', '2026-05-08 02:22:00+01'),
  ('group', 'matthew@matthewcawood.com', 'Matthew Cawood', 'Good day! The Live Practice Clinic is this coming Monday and so I have put out a poll in a new space #Community Posts, with several topic options for the session. Feel free to vote, even if you can''t make it live but want to watch the replay. I shall prepare in an enthusiastic manner!', '[]', '2026-05-08 09:36:00+01'),
  ('group', 'michaelpage05@hotmail.co.uk', 'Michael Page', '@Matthew Cawood Sorry I have found another bug. On the heat map if you hover over today it shows Fri 7 May but it is Fri 8 May. I was also wondering if it would be beneficial to have a dedicated space for feedback, bug reports and feature requests.', '[]', '2026-05-08 11:22:00+01'),
  ('group', 'danielduordoe@yahoo.co.uk', 'Daniel Duordoe', 'I watched a very interesting tutorial today on improvisation across various periods from baroque, classical, romantic to contemporary. I always assumed it was a jazz thing. Impressed!', '[]', '2026-05-08 18:17:00+01'),
  ('group', 'connieuitsu@gmail.com', 'Connie Witzoe', 'Just can''t beat your highscore on the note recognition, Matt! 😅
However it''s not showing the top 10, as it never even saves my score, and I can''t see anyone else''s score on there either. Something wrong with the system there?
Attachment image', '[]', '2026-05-15 12:21:00+01'),
  ('group', 'bobbymi003@gmail.com', 'BOBBY', 'question for early to late intermediates, at what point did you realise that you were not beginners anymore?', '[]', '2026-05-15 17:42:00+01'),
  ('group', 'samoasao@gmail.com', 'Tyler Wright', 'Hi everyone! My name is Tyler, I am a resident actor/singer at a local theater here in Arizona. I took piano lessons as a kid for quite some time from ages 8-17. I''m not at a level where I can sight read music well but I would like to get there. I can read chords from a chart ok, but I feel like they''re pretty blocky and would like them to sound better. I have a very ambitious project coming in March, I will be in a two man show called "Murder for Two" in which I will need to play piano, sing and act at the same time. I''ve had the score to practice for a few months now, but I have been terrible about practicing consistently and I need some accountability with it and a way to feel like I''m making progress. Other than that, generally I would like to be able to play to a point that I can accompany my own singing.', '[]', '2026-05-18 15:47:00+01'),
  ('group', 'danielduordoe@yahoo.co.uk', 'Daniel Duordoe', 'How are people finding two hours to practise on a weekday?! I am very jealous. Lol.', '[]', '2026-05-19 20:28:00+01');

